    "MessageDisplay": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "\"${CLAUDE_PLUGIN_ROOT}\"/hooks/message-display.mjs",
            "timeout": 10
          }
        ]
      }
    ]
  }
